settings.custom_liquid:
{% comment %} Section: Engineered for Maximum Protection (Accordion, 2-column, Dark, Centered) {% endcomment %}
<style>
  @import url('https://fonts.googleapis.com/css2?family=Anton&display=swap');

  .protection-section {
    background-color: #11151a;
    padding: 80px 24px;
    width: 100vw;
    position: relative;
    left: 50%;
    margin-left: -50vw;
    box-sizing: border-box;
  }

  .protection-section__inner {
    max-width: 1100px;
    margin: 0 auto;
  }

  .protection-section__title {
    font-family: 'Anton', sans-serif;
    font-size: 34px;
    font-weight: 400;
    color: #ffffff;
    margin: 0 0 12px 0;
    letter-spacing: 0.01em;
    text-align: center;
  }

  .protection-section__subtitle {
    font-family: Helvetica, Arial, sans-serif;
    font-size: 16px;
    color: #d4af37;
    margin: 0 0 48px 0;
    text-align: center;
  }

  .protection-section__list {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
    align-items: start;
  }

  .protection-section__item {
    border: 1px solid #2a2f38;
    background-color: #1a1f27;
    border-left: 3px solid #2a2f38;
  }

  .protection-section__item.is-open {
    border-color: #d4af37;
    border-left: 3px solid #d4af37;
  }

  .protection-section__header {
    display: flex;
    align-items: center;
    gap: 16px;
    padding: 18px 24px;
    cursor: pointer;
    background-color: #20262f;
    -webkit-tap-highlight-color: transparent;
  }

  .protection-section__icon {
    flex-shrink: 0;
    width: 44px;
    height: 44px;
    border: 1px solid #2a2f38;
    display: flex;
    align-items: center;
    justify-content: center;
    overflow: hidden;
    background-color: #1a1f27;
  }

  .protection-section__icon svg {
    width: 22px;
    height: 22px;
    color: #d4af37;
  }

  .protection-section__header-text {
    flex: 1;
    min-width: 0;
  }

  .protection-section__header-title {
    font-family: Helvetica, Arial, sans-serif;
    font-size: 16px;
    font-weight: 700;
    color: #ffffff;
    margin: 0 0 2px 0;
  }

  .protection-section__header-subtitle {
    font-family: Helvetica, Arial, sans-serif;
    font-size: 13px;
    color: #888888;
    margin: 0;
  }

  .protection-section__toggle {
    flex-shrink: 0;
    width: 32px;
    height: 32px;
    border-radius: 50%;
    border: 1px solid #d4af37;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: transform 0.25s ease;
  }

  .protection-section__toggle svg {
    width: 14px;
    height: 14px;
    color: #d4af37;
  }

  .protection-section__item.is-open .protection-section__toggle {
    transform: rotate(180deg);
  }

  .protection-section__body {
    max-height: 0;
    overflow: hidden;
    transition: max-height 0.3s ease;
  }

  .protection-section__body-inner {
    padding: 24px;
  }

  .protection-section__text {
    font-family: Helvetica, Arial, sans-serif;
    font-size: 14px;
    color: #aaaaaa;
    line-height: 1.9;
    margin: 0;
  }

  .protection-section__text strong {
    color: #d4af37;
    font-weight: 700;
  }

  @media (max-width: 768px) {
    .protection-section {
      padding: 56px 20px;
    }

    .protection-section__title {
      font-size: 24px;
    }

    .protection-section__subtitle {
      font-size: 14px;
      margin-bottom: 32px;
    }

    .protection-section__list {
      grid-template-columns: 1fr;
    }

    .protection-section__header {
      padding: 14px 16px;
      gap: 12px;
    }

    .protection-section__icon {
      width: 36px;
      height: 36px;
    }

    .protection-section__header-title {
      font-size: 14px;
    }

    .protection-section__header-subtitle {
      font-size: 12px;
    }

    .protection-section__body-inner {
      padding: 20px 16px;
    }

    .protection-section__text {
      font-size: 13px;
    }
  }
</style>

<div class="protection-section">
  <div class="protection-section__inner">

    <h2 class="protection-section__title">Engineered for Maximum Protection</h2>
    <p class="protection-section__subtitle">Built with integrity, reinforced for real-world protection.</p>

    <div class="protection-section__list" data-protection-list>

      <div class="protection-section__item is-open" data-protection-item>
        <div class="protection-section__header" data-protection-toggle>
          <div class="protection-section__icon">
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="1.6"><path stroke-linecap="round" stroke-linejoin="round" d="M12 2.25c1.5 2.25 3 4 3 6.5a3 3 0 1 1-6 0c0-1 .3-1.8.8-2.6-.3 1-.1 1.9.5 2.4-.2-2 .6-3.9 1.7-6.3Z"/><path stroke-linecap="round" stroke-linejoin="round" d="M8.5 13.5A3.5 3.5 0 0 0 12 17a3.5 3.5 0 0 0 3.5-3.5"/><path stroke-linecap="round" stroke-linejoin="round" d="M6 17.5c0 2.9 2.7 4.25 6 4.25s6-1.35 6-4.25"/></svg>
          </div>
          <div class="protection-section__header-text">
            <p class="protection-section__header-title">Hot Welding</p>
            <p class="protection-section__header-subtitle">Deeper Penetration And Strength</p>
          </div>
          <span class="protection-section__toggle">
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2.5"><path stroke-linecap="round" stroke-linejoin="round" d="m19.5 8.25-7.5 7.5-7.5-7.5"/></svg>
          </span>
        </div>
        <div class="protection-section__body">
          <div class="protection-section__body-inner">
            <p class="protection-section__text"><img src="https://www.sturdysafe.com/cdn/shop/files/thickweldongunsafe.png?v=1762460863&width=800?v=1613686330&width=800" alt="crowbar resistant safe door"> Most gun safes are made to <em>look</em> good, not to be truly tough. Because of this, many use thin "cold welds" that save time but don't hold up under pressure. At <strong>Sturdy Gun Safe</strong>, every seam is <strong>hot welded</strong>, meaning we fuse the steel together with intense heat for maximum strength and long-term durability. These deep, penetrating welds create a single, solid structure, not just pieces stuck together. Our <strong>gun safe bodies are continuously welded</strong>. The only exception is where we attach the thick steel door plates to their inner frames. Because our welds run so hot, using continuous welds there would actually warp the steel, so we use carefully placed skip welds in that one area to keep our safe and vault doors perfectly flat and aligned, without losing strength.</p>
          </div>
        </div>
      </div>

      <div class="protection-section__item" data-protection-item>
        <div class="protection-section__header" data-protection-toggle>
          <div class="protection-section__icon">
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="1.6"><path stroke-linecap="round" stroke-linejoin="round" d="M4 3.5v17M20 3.5v17M4 12h16"/><path stroke-linecap="round" stroke-linejoin="round" d="M10 8.5v-2M14 17.5v-2"/></svg>
          </div>
          <div class="protection-section__header-text">
            <p class="protection-section__header-title">Fully Recessed Door</p>
            <p class="protection-section__header-subtitle">Crowbar Resistant, Ultra-Tight Tolerances</p>
          </div>
          <span class="protection-section__toggle">
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2.5"><path stroke-linecap="round" stroke-linejoin="round" d="m19.5 8.25-7.5 7.5-7.5-7.5"/></svg>
          </span>
        </div>
        <div class="protection-section__body">
          <div class="protection-section__body-inner">
            <p class="protection-section__text"><img src="https://www.sturdysafe.com/cdn/shop/files/gunsafedoorgap.jpg?v=1613686330&width=800" alt="crowbar resistant safe door"> 
Every Sturdy Gun Safe is engineered with deep door recesses and ultra-tight door gaps that completely block pry bars. There's simply no room for a crowbar to fit. Few products on the market achieve this level of precision. On our fire-lined safe models, you can even feel and hear the airtight <em>whoosh</em> as the door seals shut, a sure sign of exceptional craftsmanship and uncompromising security.</p>
          </div>
        </div>
      </div>


      <div class="protection-section__item" data-protection-item>
        <div class="protection-section__header" data-protection-toggle>
          <div class="protection-section__icon">
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="1.6"><rect x="4" y="3" width="4" height="18" rx="1"/><rect x="16" y="3" width="4" height="18" rx="1"/></svg>
          </div>
          <div class="protection-section__header-text">
            <p class="protection-section__header-title">Exposed Hinges</p>
            <p class="protection-section__header-subtitle">Lighter To Move</p>
          </div>
          <span class="protection-section__toggle">
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2.5"><path stroke-linecap="round" stroke-linejoin="round" d="m19.5 8.25-7.5 7.5-7.5-7.5"/></svg>
          </span>
        </div>
        <div class="protection-section__body">
          <div class="protection-section__body-inner">
            <p class="protection-section__text">Sturdy Gun Safes are built with exposed hinges for practical advantages you won't get with hidden hinges. The door can be removed to make moving the safe easier, and when in use, it swings a full 180&deg; without risking hinge damage from being accidentally slammed open. Unlike hidden hinges, which are purely cosmetic, exposed hinges offer function without sacrificing security. Our safes use solid deadbolts to keep the door locked tight even if the hinges were removed.</p>
          </div>
        </div>
      </div>

      <div class="protection-section__item" data-protection-item>
        <div class="protection-section__header" data-protection-toggle>
          <div class="protection-section__icon">
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="1.6"><path stroke-linecap="round" stroke-linejoin="round" d="M5 21V4M5 4h13l-2.5 3.5L18 11H5"/></svg>
          </div>
          <div class="protection-section__header-text">
            <p class="protection-section__header-title">American Steel</p>
            <p class="protection-section__header-subtitle">No Imports, No Shortcuts</p>
          </div>
          <span class="protection-section__toggle">
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2.5"><path stroke-linecap="round" stroke-linejoin="round" d="m19.5 8.25-7.5 7.5-7.5-7.5"/></svg>
          </span>
        </div>
        <div class="protection-section__body">
          <div class="protection-section__body-inner">
            <p class="protection-section__text">We use only American-made A36 to Grade 50 steel. The result is a safe built for true security, where the thickness of the steel makes all the difference.</p>
          </div>
        </div>
      </div>

    </div>
  </div>
</div>

<script>
  (function () {
    var section = document.currentScript.previousElementSibling;
    var items = section.querySelectorAll('[data-protection-item]');

    items.forEach(function (item) {
      var toggle = item.querySelector('[data-protection-toggle]');
      var body = item.querySelector('.protection-section__body');

      function setOpen(isOpen) {
        if (isOpen) {
          item.classList.add('is-open');
          body.style.maxHeight = body.scrollHeight + 'px';
        } else {
          item.classList.remove('is-open');
          body.style.maxHeight = '0px';
        }
      }

      setOpen(item.classList.contains('is-open'));

      toggle.addEventListener('click', function () {
        setOpen(!item.classList.contains('is-open'));
      });
    });

    window.addEventListener('resize', function () {
      items.forEach(function (item) {
        if (item.classList.contains('is-open')) {
          var body = item.querySelector('.protection-section__body');
          body.style.maxHeight = body.scrollHeight + 'px';
        }
      });
    });
  })();
</script>
